pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and the sent value; for admissible domain keep value wide
    function testFuzz_property(address caller, uint256 value) public {
        // keep caller non-zero to be realistic
        vm.assume(caller != address(0));
        // bound value to a reasonably large range including 1 ether and 2 ether
        uint256 val = bound(value, 0, 10 ether);

        // prepare caller with balance
        vm.deal(caller, 20 ether);

        // try calling lockInGuess with fuzzed value, capture whether it succeeded (did not revert)
        bool ok;
        bytes32 h = keccak256(abi.encodePacked("guess"));
        vm.prank(caller);
        try c.lockInGuess{value: val}(h) {
            ok = true;
        } catch {
            ok = false;
        }

        // GENERAL RULE: Reference accepts iff msg.value == 1 ether. We assert that for this call the contract
        // accepted the call exactly when val == 1 ether. This holds for the reference for ALL inputs, but
        // the mutant (which requires 2 ether) will differ for some fuzzed val (e.g., val == 1 ether)
        assertTrue(ok == (val == 1 ether));
    }
}

